# Algebraic numbers in a number field, after AlgebraicNumber in
# sympy/core/numbers.py, and the subfield functions of
# sympy/polys/numberfields/subfield.py and utilities.py (isolate).

#' Algebraic numbers
#'
#' `AlgebraicNumber(expr, coeffs, alias)` is the element
#' `coeffs[1]*theta^(n-1) + ... + coeffs[n]` of the number field generated by
#' `theta = expr`, as SymPy's `AlgebraicNumber`; by default the element is
#' `theta` itself (`coeffs = c(1, 0)`). `expr` may also be
#' `list(minpoly, root)`. It prints as its value, or as a polynomial in
#' `alias` when one is given. [as_expr()] gives the value, [coeffs()] the
#' coordinates, and [minimal_polynomial()] its minimal polynomial.
#' `field_element(a, coeffs)` is another element of the same field,
#' `is_primitive_element(a)` tells whether `a` generates its field,
#' `to_primitive_element(a)` makes `a` the generator of a new field,
#' `minpoly_of_element(a)` and `to_root(a)` are the minimal polynomial and an
#' explicit value of `a`, and `isolate(a, eps)` a rational interval that
#' isolates the real algebraic number `a` among the roots of its minimal
#' polynomial (of width below `eps` when given).
#'
#' @param expr An algebraic number, an `AlgebraicNumber`, or
#'   `list(minpoly, root)`.
#' @param coeffs Coordinates in the power basis, highest power first.
#' @param alias A symbol (or name) printed for the generator.
#' @param gen The variable of the minimal polynomial.
#' @param a An `AlgebraicNumber` (or an algebraic number for `isolate()`).
#' @param x A variable.
#' @param eps Width of the isolating interval.
#' @param fast Use fast refinement steps.
#' @return An `AlgebraicNumber`, an expression, a logical, or a list.
#' @examples
#' a <- AlgebraicNumber(sqrt(Integer(2)), c(1, 1))
#' a
#' coeffs(a)
#' minimal_polynomial(a, Symbol("x"))
#' AlgebraicNumber(sqrt(Integer(2)), alias = "theta")
#' isolate(sqrt(Integer(2)), eps = Rational(1, 100))
#' @name AlgebraicNumber
NULL

#' @rdname AlgebraicNumber
#' @export
AlgebraicNumber <- function(expr, coeffs = NULL, alias = NULL, gen = NULL) {
  rep0 <- NULL; alias0 <- NULL
  if (is.list(expr) && !is_sym(expr)) {
    mp <- expr[[1L]]; root <- as_sym(expr[[2L]])
    mp <- if (inherits(mp, "Poly")) as_expr(mp) else as_sym(mp)
    mvar <- free_symbols(mp)[[1L]]
  } else {
    expr <- as_sym(expr)
    if (expr$type == "AlgebraicNumber") {
      ex <- expr$extra
      mp <- ex$minpoly; mvar <- ex$mvar; root <- ex$root; rep0 <- ex$rep; alias0 <- ex$alias
    } else {
      root <- expr
      mvar <- if (is.null(gen)) Dummy("x") else as_sym(gen)
      mp <- minimal_polynomial(expr, mvar)
    }
  }
  m <- up_from_qpoly(expr_to_qpoly(expand(mp), list(mvar), strict = TRUE), 1L)
  rep <- if (is.null(coeffs)) gmp::as.bigq(c(1, 0))
         else up_trim(gmp::as.bigq(vapply(as.list(coeffs), function(c) as.character(as_sym(c)$value), "")))
  # dup_compose(rep, rep0): an element of an element's field
  if (!is.null(rep0)) {
    out <- .bq0()
    for (i in seq_along(rep)) out <- up_add(up_mul(out, rep0), rep[i])
    rep <- up_trim(out)
  }
  if (up_deg(rep) >= up_deg(m)) rep <- up_divmod(rep, m)$r
  alias <- if (!is.null(alias)) alias else alias0
  if (!is.null(alias) && !is_sym(alias)) alias <- Symbol(as.character(alias))
  new_sym("AlgebraicNumber", list(),
          extra = list(root = root, rep = rep, minpoly = mp, mvar = mvar, alias = alias),
          key = paste0("AN(", root$key, ";", paste(as.character(rep), collapse = ","), ";",
                       if (is.null(alias)) "" else alias$key, ")"))
}

.an_check <- function(a) {
  a <- as_sym(a)
  if (a$type != "AlgebraicNumber") stop("expected an AlgebraicNumber", call. = FALSE)
  a
}

# as_poly(x).as_expr().expand()
.an_value <- function(a, x = NULL) {
  ex <- a$extra
  v <- if (is.null(x)) ex$root else x
  rep <- ex$rep
  if (!length(rep)) return(S_Zero)
  n <- length(rep)
  expand(.add(lapply(seq_len(n), function(i) .mul(list(make_rational(rep[i]), .pow(v, .int(n - i)))))))
}

register_str_printer("AlgebraicNumber", function(e)
  .str(if (is.null(e$extra$alias)) .an_value(e) else .an_value(e, e$extra$alias)))
register_latex_printer("AlgebraicNumber", function(e)
  .latex(if (is.null(e$extra$alias)) .an_value(e) else .an_value(e, e$extra$alias)))
register_neval("AlgebraicNumber", function(e, env) .neval(.an_value(e), env))

#' @rdname AlgebraicNumber
#' @export
field_element <- function(a, coeffs) {
  a <- .an_check(a)
  AlgebraicNumber(list(a$extra$minpoly, a$extra$root), coeffs, alias = a$extra$alias)
}

#' @rdname AlgebraicNumber
#' @export
is_primitive_element <- function(a) {
  a <- .an_check(a)
  r <- a$extra$rep
  (length(r) == 2L && r[1L] == 1 && r[2L] == 0)
}

.an_primitive <- function(a) if (is_primitive_element(a)) a else field_element(a, c(1, 0))

#' @rdname AlgebraicNumber
#' @export
minpoly_of_element <- function(a, x = NULL) {
  a <- .an_check(a)
  if (is_primitive_element(a)) {
    mp <- a$extra$minpoly
    return(if (is.null(x)) mp else subs(mp, a$extra$mvar, as_sym(x)))
  }
  x <- if (is.null(x)) Dummy("x") else as_sym(x)
  minimal_polynomial(.an_value(a), x)
}

#' @rdname AlgebraicNumber
#' @export
to_root <- function(a) {
  a <- .an_check(a)
  if (is_primitive_element(a) && a$extra$root$type != "AlgebraicNumber") return(a$extra$root)
  x <- Dummy("x")
  m <- minpoly_of_element(a, x)
  rs <- roots(m, x, multiple = TRUE)
  ex <- .an_value(a)
  if (length(rs) == degree(m, x)) {
    if (length(rs) == 1L) return(rs[[1L]])
    v <- as.complex(N(ex, 30))
    d <- vapply(rs, function(r) Mod(as.complex(N(r, 30)) - v), 0)
    return(rs[[which.min(d)]])
  }
  ex
}

#' @rdname AlgebraicNumber
#' @export
to_primitive_element <- function(a) {
  a <- .an_check(a)
  if (is_primitive_element(a)) return(a)
  x <- Dummy("x")
  AlgebraicNumber(list(minpoly_of_element(a, x), to_root(a)))
}

#' @rdname AlgebraicNumber
#' @export
isolate <- function(a, eps = NULL, fast = FALSE) {
  a <- as_sym(a)
  if (a$type %in% c("Integer", "Rational")) return(list(a, a))
  if (a$type == "AlgebraicNumber") a <- .an_value(a)
  z <- .mpeval_adaptive(a, 64L)
  if (is.null(z) || z$im$m != 0) stop("complex algebraic numbers are not supported", call. = FALSE)
  x <- Dummy("x")
  mp <- minimal_polynomial(a, x)
  ivs <- intervals(mp, x, sqf = TRUE)
  for (prec in c(64L, 128L, 256L, 512L, 1024L, 2048L)) {
    z <- .mpeval_adaptive(a, prec)
    v <- .mp_to_q(z$re)
    err <- gmp::as.bigq(1, gmp::as.bigz(2)^max(1, prec - max(0, .mp_mag(z$re)) - 4))
    hit <- Filter(function(iv) gmp::as.bigq(iv[[1L]]$value) <= v - err && v + err <= gmp::as.bigq(iv[[2L]]$value), ivs)
    if (length(hit) == 1L) {
      iv <- hit[[1L]]
      if (!is.null(eps)) iv <- refine_root(mp, iv[[1L]], iv[[2L]], eps = eps, fast = fast, x = x)
      return(iv)
    }
  }
  stop("cannot isolate ", .str(a), call. = FALSE)
}

#' @rdname primitive_element
#' @export
field_isomorphism <- function(a, b) {
  a <- as_sym(a); b <- as_sym(b)
  if (a$type != "AlgebraicNumber") a <- AlgebraicNumber(a)
  if (b$type != "AlgebraicNumber") b <- AlgebraicNumber(b)
  a <- to_primitive_element(a); b <- to_primitive_element(b)
  if (identical(a$key, b$key)) return(lapply(as.list(a$extra$rep), make_rational))
  x <- Dummy("x")
  ma <- minpoly_of_element(a, x); mb <- minpoly_of_element(b, x)
  n <- degree(ma, x); m <- degree(mb, x)
  if (n == 1) return(list(a$extra$root))
  if (m %% n != 0) return(NULL)
  # field_isomorphism_factor: a linear factor of the minimal polynomial of a
  # over Q(b) whose root is a
  K <- .nf_field(list(b$extra$root))
  fl <- .nf_factor(.nfp_from_expr(ma, x, K), K)
  va <- as.complex(N(a$extra$root, 40))
  for (fk in fl$factors) {
    f <- fk[[1L]]
    if (length(f) != 2L) next
    c <- up_trim(-f[[2L]])
    r <- .nfe_to_expr(c, K)
    if (Mod(as.complex(N(r, 40)) - va) < 1e-25 * max(1, Mod(va))) return(lapply(as.list(c), make_rational))
  }
  NULL
}

#' @rdname primitive_element
#' @export
to_number_field <- function(extension, theta = NULL, gen = NULL, alias = NULL) {
  exts <- if (is_sym(extension)) list(extension) else as.list(extension)
  if (length(exts) == 2L && !is_sym(extension) && is.null(names(exts)) && isTRUE(attr(extension, "tuple")))
    return(AlgebraicNumber(exts, alias = alias))
  exts <- lapply(exts, as_sym)
  pe <- primitive_element(exts, gen)
  root <- expand(.add(Map(function(c, e) .mul(list(c, e)), pe[[2L]], exts)))
  mvar <- free_symbols(pe[[1L]])[[1L]]
  if (is.null(theta)) return(AlgebraicNumber(list(pe[[1L]], root), alias = alias))
  theta <- as_sym(theta)
  if (theta$type != "AlgebraicNumber") theta <- AlgebraicNumber(theta, gen = gen, alias = alias)
  cf <- field_isomorphism(root, theta)
  if (is.null(cf)) stop(IsomorphismFailed(paste0(.str(root), " is not in a subfield of ", .str(theta$extra$root))))
  AlgebraicNumber(theta, cf, alias = alias)
}
